def transform(grid):
    H = len(grid); W = len(grid[0])
    # try horizontal full-color rows
    rows = [r for r in range(H)
            if len(set(grid[r])) == 1 and grid[r][0] != 0]
    if rows:
        n = len(rows)
        f = {}
        ok = True
        for r in rows:
            k = r % n
            if k in f and f[k] != grid[r][0]:
                ok = False
            f[k] = grid[r][0]
        if ok and len(f) == n:
            return [[f[r % n] for c in range(W)] for r in range(H)]
    # try anti-diagonals (r+c = s)
    d = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v:
                d.setdefault(r + c, set()).add(v)
    ds = [s for s in d if len(d[s]) == 1]
    n = len(ds)
    f = {s % n: next(iter(d[s])) for s in ds}
    if len(f) == n:
        return [[f[(r + c) % n] for c in range(W)] for r in range(H)]
    # fallback: fill missing residues with nearest available cyclically
    if ds:
        n = len(ds)
        f = {s % n: next(iter(d[s])) for s in ds}
        for k in range(n):
            if k not in f:
                best = None; bd = n
                for kk in f:
                    dist = min((k - kk) % n, (kk - k) % n)
                    if dist < bd:
                        bd = dist; best = kk
                f[k] = f[best]
        if (r + c) % n in f:
            return [[f[(r + c) % n] for c in range(W)] for r in range(H)]
    return [row[:] for row in grid]
